
import type { CreateOrderLineItem } from './CreateOrderLineItem.js';
import type { DeliveryAddressResource } from './DeliveryAddressResource.js';
import type { DeliveryBuyerLocationResource } from './DeliveryBuyerLocationResource.js';
import type { DeliveryInputRequirement } from './DeliveryInputRequirement.js';
import type { DeliveryMerchantDiagnostic } from './DeliveryMerchantDiagnostic.js';
import type { DeliveryPreviewChoiceGroupResource } from './DeliveryPreviewChoiceGroupResource.js';

export type DeliveryPreview = { "buyer_location"?: DeliveryBuyerLocationResource; "choice_groups": Array<DeliveryPreviewChoiceGroupResource>; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "delivery_method_ids": Array<string>; "destination_address"?: DeliveryAddressResource; /** RFC3339 timestamp. Format: date-time. */ "evaluated_at": string; "evaluation_status": "complete" | "incomplete" | "degraded" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "expires_at": string; /** Inputs the delivery methods need. A quote requirement, such as the destination address, is input a method needs before Flint can price it. A selection requirement is input a delivery selection needs before payment, such as a recipient field or delivery window an option requires. A method that waits on the buyer's address or store, or on an address the buyer must correct, already lists the recipient fields it requires. Those requirements name the method's choice group and have no delivery_option_ids. */ "input_requirements": Array<DeliveryInputRequirement>; "line_items": Array<CreateOrderLineItem>; "merchant_diagnostics": Array<DeliveryMerchantDiagnostic>; /** The delivery question this preview answers. - `delivery_options`: Evaluates delivery methods and prices for the supplied items and buyer location. */ "mode": "delivery_options" | (string & {}); "pickup_location_id"?: string; "selection_authority": boolean; };
